using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Media3D;using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Geometry;using ToneCustoms.ShellStudio.Materials;
namespace ToneCustoms.ShellStudio.Editor;
public sealed class Viewport3DControl:Grid {readonly Viewport3D view=new();readonly Model3DGroup scene=new();readonly PerspectiveCamera camera=new(){FieldOfView=55,UpDirection=new Vector3D(0,0,1)};readonly Dictionary<Model3D,Guid> objectModels=new();readonly WallMeshBuilder wallMeshes=new();readonly StairMeshBuilder stairMeshes=new();readonly ViewportMaterialResolver materials=new();ShellProject? project;Guid? selected;Point? orbitStart;Point? dragStart;Vec3? dragPositionStart,dragRotationStart,dragScaleStart;GizmoAxis activeAxis=GizmoAxis.None;TransformMode mode=TransformMode.Move;bool openingPlacement,openingDoor;float openingWidth=1,openingHeight=2.1f,openingSill;double yaw=.7,pitch=.55,distance=18;Point3D cameraTarget=new(0,0,1.5);public event Action<Guid>? ObjectSelected;public event Action? ObjectTransformed;public event Action<Guid,float,float,float,bool>? WallOpeningRequested;public Viewport3DControl(){Focusable=true;Background=new SolidColorBrush(Color.FromRgb(12,12,16));view.Camera=camera;view.Children.Add(new ModelVisual3D{Content=scene});Children.Add(view);MouseWheel+=Wheel;MouseRightButtonDown+=OrbitDown;MouseRightButtonUp+=OrbitUp;MouseLeftButtonDown+=LeftDown;MouseLeftButtonUp+=LeftUp;MouseMove+=Move;KeyDown+=Keys;Loaded+=(_,_)=>{UpdateCamera();RenderScene();};}public void SetProject(ShellProject p,Guid? selectedId=null){project=p;selected=selectedId;RenderScene();}public void SetMode(TransformMode value){mode=value;openingPlacement=false;RenderScene();}public void FocusSelection(){if(project==null||selected==null)return;var o=project.Objects.FirstOrDefault(x=>x.Id==selected);if(o==null)return;cameraTarget=new Point3D(o.Position.X,o.Position.Y,o.Position.Z);distance=Math.Clamp(Math.Max(o.Scale.X,Math.Max(o.Scale.Y,o.Scale.Z))*3,4,30);UpdateCamera();}public void BeginWallOpeningPlacement(bool door,float width,float height,float sill){openingPlacement=true;openingDoor=door;openingWidth=Math.Max(.1f,width);openingHeight=Math.Max(.1f,height);openingSill=door?0:Math.Max(0,sill);Cursor=Cursors.Cross;RenderScene();}public void CancelWallOpeningPlacement(){openingPlacement=false;Cursor=Cursors.Arrow;RenderScene();}public void RenderScene(){scene.Children.Clear();objectModels.Clear();scene.Children.Add(new AmbientLight(Color.FromRgb(110,110,125)));scene.Children.Add(new DirectionalLight(Colors.White,new Vector3D(-.4,.6,-1)));DrawGrid();if(project==null)return;foreach(var o in project.Objects){var m=Model(o,o.Id==selected);objectModels[m]=o.Id;scene.Children.Add(m);}if(!openingPlacement&&selected is Guid id){var o=project.Objects.FirstOrDefault(x=>x.Id==id);if(o!=null)DrawGizmo(o);}}GeometryModel3D Model(SceneObject o,bool active){MeshGeometry3D mesh;if(o.Type==SceneObjectType.Wall&&project!=null)mesh=wallMeshes.Build(o,project.WallOpenings.Where(x=>x.WallId==o.Id));else if(o.Type==SceneObjectType.Stairs)mesh=stairMeshes.Build(o);else mesh=BoxMesh(o.Scale);var fallback=active?Color.FromRgb(176,132,245):o.Type==SceneObjectType.Prop?Color.FromRgb(125,90,190):Color.FromRgb(105,76,165);var mat=project==null?new DiffuseMaterial(new SolidColorBrush(fallback)):materials.Resolve(project,o,fallback);var model=new GeometryModel3D(mesh,mat){BackMaterial=mat};var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),o.Rotation.X)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,1,0),o.Rotation.Y)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),o.Rotation.Z)));var z=o.Type is SceneObjectType.Wall or SceneObjectType.Stairs?o.Position.Z-o.Scale.Z/2:o.Position.Z;t.Children.Add(new TranslateTransform3D(o.Position.X,o.Position.Y,z));model.Transform=t;return model;}static MeshGeometry3D BoxMesh(Vec3 scale){var sx=Math.Max(.02,scale.X)/2;var sy=Math.Max(.02,scale.Y)/2;var sz=Math.Max(.02,scale.Z)/2;return new MeshGeometry3D{Positions=new Point3DCollection{new(-sx,-sy,-sz),new(sx,-sy,-sz),new(sx,sy,-sz),new(-sx,sy,-sz),new(-sx,-sy,sz),new(sx,-sy,sz),new(sx,sy,sz),new(-sx,sy,sz)},TriangleIndices=new Int32Collection{0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7}};}void DrawGizmo(SceneObject o){var p=new Point3D(o.Position.X,o.Position.Y,o.Position.Z);var width=mode==TransformMode.Rotate?.1:.065;scene.Children.Add(Axis(p,new Vector3D(2.4,0,0),Colors.Red,GizmoAxis.X,width));scene.Children.Add(Axis(p,new Vector3D(0,2.4,0),Colors.LimeGreen,GizmoAxis.Y,width));scene.Children.Add(Axis(p,new Vector3D(0,0,2.4),Colors.DodgerBlue,GizmoAxis.Z,width));}GeometryModel3D Axis(Point3D p,Vector3D d,Color c,GizmoAxis axis,double width){var m=Line(p,p+d,width,c);m.SetValue(FrameworkElement.TagProperty,axis);return m;}void DrawGrid(){for(int i=-30;i<=30;i++){var major=i%5==0;var c=major?Color.FromRgb(58,58,72):Color.FromRgb(38,38,48);scene.Children.Add(Line(new Point3D(i,-30,0),new Point3D(i,30,0),major?.016:.009,c));scene.Children.Add(Line(new Point3D(-30,i,0),new Point3D(30,i,0),major?.016:.009,c));}}GeometryModel3D Line(Point3D a,Point3D b,double width,Color color){var d=b-a;var len=d.Length;var mesh=new MeshGeometry3D{Positions=new Point3DCollection{new(-width,-len/2,0),new(width,-len/2,0),new(width,len/2,0),new(-width,len/2,0)},TriangleIndices=new Int32Collection{0,1,2,0,2,3}};var mat=new DiffuseMaterial(new SolidColorBrush(color));var m=new GeometryModel3D(mesh,mat){BackMaterial=mat};var angle=Math.Atan2(d.Y,d.X)*180/Math.PI-90;var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),angle)));if(Math.Abs(d.Z)>Math.Abs(d.X)+Math.Abs(d.Y))t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),90)));t.Children.Add(new TranslateTransform3D((a.X+b.X)/2,(a.Y+b.Y)/2,(a.Z+b.Z)/2));m.Transform=t;return m;}void OrbitDown(object s,MouseButtonEventArgs e){Focus();orbitStart=e.GetPosition(this);CaptureMouse();}void OrbitUp(object s,MouseButtonEventArgs e){orbitStart=null;if(activeAxis==GizmoAxis.None&&IsMouseCaptured)ReleaseMouseCapture();}void LeftDown(object s,MouseButtonEventArgs e){Focus();var hit=VisualTreeHelper.HitTest(view,e.GetPosition(view)) as RayMeshGeometry3DHitTestResult;if(hit?.ModelHit is not Model3D model)return;if(openingPlacement&&objectModels.TryGetValue(model,out var wallId)&&project!=null){var wall=project.Objects.FirstOrDefault(x=>x.Id==wallId);if(wall?.Type==SceneObjectType.Wall){var local=hit.PointHit;var inv=model.Transform?.Inverse;if(inv!=null)local=inv.Transform(hit.PointHit);var offset=(float)local.X+wall.Scale.X/2;offset=Math.Clamp(offset,openingWidth/2,Math.Max(openingWidth/2,wall.Scale.X-openingWidth/2));WallOpeningRequested?.Invoke(wall.Id,offset,openingWidth,openingHeight,openingDoor);selected=wall.Id;CancelWallOpeningPlacement();ObjectSelected?.Invoke(wall.Id);e.Handled=true;return;}}if(model.GetValue(FrameworkElement.TagProperty) is GizmoAxis axis&&axis!=GizmoAxis.None&&selected!=null){activeAxis=axis;dragStart=e.GetPosition(this);var o=project?.Objects.FirstOrDefault(x=>x.Id==selected);if(o!=null){dragPositionStart=o.Position;dragRotationStart=o.Rotation;dragScaleStart=o.Scale;}CaptureMouse();e.Handled=true;return;}if(objectModels.TryGetValue(model,out var id)){selected=id;ObjectSelected?.Invoke(id);RenderScene();e.Handled=true;}}void LeftUp(object s,MouseButtonEventArgs e){activeAxis=GizmoAxis.None;dragStart=null;dragPositionStart=dragRotationStart=dragScaleStart=null;if(orbitStart==null&&IsMouseCaptured)ReleaseMouseCapture();}void Move(object s,MouseEventArgs e){if(orbitStart!=null&&e.RightButton==MouseButtonState.Pressed){var p=e.GetPosition(this);yaw+=(p.X-orbitStart.Value.X)*.01;pitch=Math.Clamp(pitch+(p.Y-orbitStart.Value.Y)*.01,-1.35,1.35);orbitStart=p;UpdateCamera();return;}if(activeAxis==GizmoAxis.None||dragStart==null||selected==null||project==null||e.LeftButton!=MouseButtonState.Pressed)return;var o=project.Objects.FirstOrDefault(x=>x.Id==selected);if(o==null)return;var now=e.GetPosition(this);var raw=(float)((now.X-dragStart.Value.X-(now.Y-dragStart.Value.Y))*.015);if(mode==TransformMode.Move&&dragPositionStart is Vec3 p){var next=activeAxis switch{GizmoAxis.X=>new Vec3(p.X+raw,p.Y,p.Z),GizmoAxis.Y=>new Vec3(p.X,p.Y+raw,p.Z),GizmoAxis.Z=>new Vec3(p.X,p.Y,p.Z+raw),_=>p};var g=project.Settings.GridSize;if(g>0)next=new Vec3(Snap(next.X,g),Snap(next.Y,g),Snap(next.Z,g));o.Position=next;}else if(mode==TransformMode.Rotate&&dragRotationStart is Vec3 r){var degrees=MathF.Round(raw*15f)*5f;o.Rotation=activeAxis switch{GizmoAxis.X=>new Vec3(r.X+degrees,r.Y,r.Z),GizmoAxis.Y=>new Vec3(r.X,r.Y+degrees,r.Z),GizmoAxis.Z=>new Vec3(r.X,r.Y,r.Z+degrees),_=>r};}else if(mode==TransformMode.Scale&&dragScaleStart is Vec3 sc){var amount=raw*.35f;o.Scale=activeAxis switch{GizmoAxis.X=>new Vec3(Math.Max(.05f,sc.X+amount),sc.Y,sc.Z),GizmoAxis.Y=>new Vec3(sc.X,Math.Max(.05f,sc.Y+amount),sc.Z),GizmoAxis.Z=>new Vec3(sc.X,sc.Y,Math.Max(.05f,sc.Z+amount)),_=>sc};}RenderScene();ObjectTransformed?.Invoke();}void Keys(object s,KeyEventArgs e){var pan=Math.Max(.2,distance*.025);if(e.Key==Key.F){FocusSelection();e.Handled=true;return;}if(e.Key==Key.Home){cameraTarget=new Point3D(0,0,1.5);distance=18;UpdateCamera();e.Handled=true;return;}if(e.Key==Key.Left)cameraTarget.X-=pan;if(e.Key==Key.Right)cameraTarget.X+=pan;if(e.Key==Key.Up)cameraTarget.Y+=pan;if(e.Key==Key.Down)cameraTarget.Y-=pan;UpdateCamera();}void Wheel(object s,MouseWheelEventArgs e){distance=Math.Clamp(distance-e.Delta/120.0,2,100);UpdateCamera();}void UpdateCamera(){var cp=Math.Cos(pitch);var offset=new Vector3D(Math.Cos(yaw)*cp*distance,Math.Sin(yaw)*cp*distance,Math.Sin(pitch)*distance);camera.Position=cameraTarget+offset;camera.LookDirection=cameraTarget-camera.Position;}static float Snap(float v,float g)=>MathF.Round(v/g)*g;enum GizmoAxis{None,X,Y,Z}}
